namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => 0
    };
}
EOF
cat > CheckoutPricing.Domain/PromoCodePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int WelcomeCents = 500;
    private const int SummerPercent = 10;
    private const int SummerCapCents = 1_500;

    public static int Discount(string? promoCode, int amountLeftCents) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => WelcomeCents,
            "SUMMER10" => Math.Min(SummerCapCents, amountLeftCents * SummerPercent / 100),
            _ => 0
        };
}
EOF
cat > CheckoutPricing.Domain/DiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int Total(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyDiscountPolicy.LoyaltyPart(subtotalCents, tier);
        var promoPart = PromoCodePolicy.Discount(promoCode, subtotalCents - loyaltyPart);
        return Math.Min(subtotalCents, loyaltyPart + promoPart);
    }
}
EOF
cat > CheckoutPricing.Domain/ShippingPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardCents = 490;
    private const int ExpressCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int Fee(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableTotalCents, tier);

    private static int ExpressFee(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardCents;
}
EOF
